from PIL import Image
from collections import deque
im=Image.open('sheet.png'); w,h=im.size; alpha=im.getchannel('A').tobytes()
for threshold in [32,64,128,192,240]:
 b=bytearray(x>=threshold for x in alpha); comps=[]
 for i in range(len(b)):
  if not b[i]:continue
  b[i]=0;q=deque([i]);n=0;x0=x1=i%w;y0=y1=i//w
  while q:
   p=q.popleft();y,x=divmod(p,w);n+=1;x0=min(x0,x);x1=max(x1,x);y0=min(y0,y);y1=max(y1,y)
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     nx=x+dx;ny=y+dy;j=p+dy*w+dx
     if 0<=nx<w and 0<=ny<h and b[j]: b[j]=0;q.append(j)
  if n>3000:comps.append((n,(x0,y0,x1+1,y1+1)))
 print(threshold,len(comps))
 if threshold==128:
  for c in sorted(comps,key=lambda c:(c[1][1]//230,c[1][0])):print(c)
